                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));

        // 失败不占 requestId：先因授权缺失 422，补齐授权后同 requestId 成功
        Ctx ctx2 = newCtx();
