        getPlaceholders(ch1).andExpect(jsonPath("$.placeholders.length()").value(0));

        // 组明细保留撤销信息；撤销历史可查且不可变
        getGroup(ctx, "sc-1")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("REVOKED"))
