        MvcResult rejected = createLock(ctx, "req-422", "sc-422",
                        List.of(ok0, ok1, noDraft, noGrant, occupied, ghost), PLANNED)
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("SIMULCAST_VALIDATION_FAILED"))
